## 2

### 문제 - <code>피로도</code>

### 알고리즘 설계

제가 골랐지만 개인적으로 너무 어려웠어요 ㅜ.ㅠ 다른분 풀이 보고도 이해가 안돼서 그냥 좀 며칠 쉬다가 풀었네요 ,,, 잉잉

[체력, [ [최소필요피로도, 소모필요도] , ... ] 식의 파라미터를 받아서 최대로 돌 수 있는 던전 수를 계산하는 문제였습니다!

풀이설명은 코드에 주석으로 적어놨습니다!!


### 풀이 코드

```javascript
function solution(k, dungeons) {
  // 던전을 최소 요구 피로도 기준으로 정렬
  dungeons.sort((a, b) => a[0] - b[0]);

  let maxCount = 0;

  // 백트래킹을 사용하여 던전을 탐험하는 함수 (전부 다 돌고 그중에 maxCount를 반환하는 식)
  function explore(remainingK, exploredCount, isVisitedArray) {
    maxCount = Math.max(maxCount, exploredCount);

    dungeons.forEach(([최소필요피로도, 소모피로도], index) => {
      if (!isVisitedArray[index] && remainingK >= 최소필요피로도) {
        // 만약 방문하지 않았고, 남아있는체력이 최소필요도보다 크다면 if문 내부 진행
          
         isVisitedArray[index] = true;  // 이번에 시작한 던전을 true로 바꾸고 그 array를 넣은 explore 함수를 다시 돌림 (재귀)
        explore(remainingK - 소모피로도, exploredCount + 1, isVisitedArray);
        
        // 다음을 위해 false로 초기화
        isVisitedArray[index] = false;
      }
    });
  }

  // 초기 상태에서 탐험 시작
  explore(k, 0, new Array(dungeons.length).fill(false));

  return maxCount;
}

```

